#!/usr/bin/env node
/**
 * Can a THIRD-PARTY package expose a read-only Typert Remote that the browser can call? (R33 spike, T-401 ②)
 *
 * WHY THIS EXISTS: the last open item of M4-a is "the tab shows the same conclusion as the CLI", and
 * the only honest source for that is a Host-side read-only Remote. Upstream's own inventory plugin
 * (`@deepseek-ai/dsh-host-plugin-inventory`) is such a Remote, but it is BUILT IN and generated by
 * `@deepseek-ai/dsh-typert-generator`; whether an outside package can hand-write the same shape is an
 * empirical question, not a documentation one. So this script builds a throwaway package that exports
 * `./typert` + `./client`, boots a real Host with it, and records what actually happens.
 *
 * WHAT IT DOES NOT DO: it does not touch `~/.dsh`, does not read credentials, does not publish, and it
 * approves no build script. The spike package answers `ping` with a constant — it proves a CHANNEL,
 * never a conclusion.
 *
 *   node scripts/record_remote_spike.mjs --dsh-main <bin.js> --install <dir> --stamp <iso>
 *
 * Exit codes: 0 artifact written (whatever it says) · 2 bad usage.
 */

import { spawn } from 'node:child_process'
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { homedir, tmpdir } from 'node:os'
import { basename, isAbsolute, join, resolve } from 'node:path'
import process from 'node:process'
import { findBrowser } from '../packages/probe/dist/render.js'
import { abs, isoStamp } from './lib/kit.mjs'

const argv = process.argv.slice(2)
const argOf = (name, fallback) => {
  const index = argv.indexOf(name)
  return index === -1 ? fallback : (argv[index + 1] ?? fallback)
}
const pathFor = (value) => (isAbsolute(value) ? value : resolve(abs('.'), value))

const stamp = isoStamp(String(argOf('--stamp', new Date().toISOString())))
const dshMain = pathFor(String(argOf('--dsh-main', '')))
const outDir = pathFor(argOf('--out', 'data/results'))
const label = String(argOf('--label', 'spike-remote')).replace(/[^a-zA-Z0-9._-]+/g, '-')
/**
 * Which third-party channel is under test:
 *   `typert` — a hand-written host-face manifest (upstream's own way: `ctx.typert.register`)
 *   `route`  — a same-origin read-only HTTP route on the Host's webserver (`ctx.webServer.register`)
 * Both are legitimate answers to "can the tab show a CLI-sourced conclusion"; they cost differently.
 */
const channel = String(argOf('--channel', 'typert'))
const bootTimeoutMs = Number(argOf('--boot-timeout-ms', '120000'))
if (stamp === null || !existsSync(dshMain)) {
  process.stderr.write('usage: node scripts/record_remote_spike.mjs --dsh-main <bin.js> --stamp <iso>\n')
  process.exit(2)
}

const root = join(tmpdir(), 'dsh-triage-spike', `${label}-${Date.now().toString(36)}`)
const home = join(root, 'home')
const profileDir = join(home, 'profiles', 'web')
const pkgDir = join(profileDir, '.spike-bundle', 'spike')
const steps = []
let hostPid
const redactions = [abs('.'), homedir(), tmpdir()]
const clean = (value) => {
  let text = String(value ?? '')
  for (const root_ of redactions) {
    for (const variant of [root_, root_.replaceAll('\\', '/')]) text = text.split(variant).join(root_ === abs('.') ? '<repo>' : '~')
  }
  return text
}
const record = (id, status, detail, extra = {}) => steps.push({ id, status, detail: clean(detail), ...extra })
const sha256 = (text) => createHash('sha256').update(text).digest('hex')

/**
 * The spike package.
 *
 * Three pieces, and each one is a contract we are testing:
 *   `./typert`  — a hand-written TYPERT manifest (upstream generates its own; we type it by hand)
 *   main export — a Cordis service class extending `TypertRemoteService` + the Remote marker
 *   `./client`  — a browser half that calls the Remote and publishes what came back
 */
function writeSpikePackage() {
  mkdirSync(pkgDir, { recursive: true })
  writeFileSync(
    join(pkgDir, 'package.json'),
    `${JSON.stringify(
      {
        name: 'dsh-remote-spike',
        version: '0.0.0',
        private: true,
        type: 'module',
        main: './index.js',
        exports: {
          '.': './index.js',
          './client': './client.js',
          './typert': './typert.host.js',
          './package.json': './package.json',
        },
        dsh: {
          bundle: { patch: './cordis.patch.yml' },
          client: { platform: 'web', inject: ['@deepseek-ai/dsh-api-remotes'] },
        },
        /*
         * Declared on purpose: a package that imports the protocol MUST depend on it, otherwise the
         * import resolves only if the store happens to hoist it (measured R33: without this the host
         * half mounted as a failed row and nothing said why).
         */
        dependencies: {
          '@deepseek-ai/dsh-typert-protocol': '0.2.1-rc.4',
          zod: '4.4.3',
        },
      },
      null,
      2,
    )}\n`,
    'utf8',
  )
  writeFileSync(
    join(pkgDir, 'cordis.patch.yml'),
    ['# Spike row: bare package name on purpose (R31/BS-35: a subpath silently drops the client half).', '- insert:', '    - id: compat-spike', '      name: dsh-remote-spike', ''].join('\n'),
    'utf8',
  )
  /*
   * Host half, one per channel.
   *
   * `typert`: a `TypertRemoteService` whose `ping` method carries the Remote marker. The marker is
   * normally written by the `@Remote()` decorator; plain `.js` has no decorator syntax, so it is
   * defined by hand under the protocol's own descriptor key.
   *
   * `route`: a named same-origin HTTP route on the Host's webserver. No generator, no schema pair,
   * no browser-side face — the tab would simply `fetch()` it with the session cookie.
   */
  const hostHalf =
    channel === 'route'
      ? [
          "export const name = 'compat-spike'",
          "export const inject = ['webServer']",
          '',
          'export function apply(ctx) {',
          '  /*',
          '   * Read-only on purpose: a GET answers a constant and nothing is written. A product route would',
          '   * answer the same payload the CLI prints, but it must first pass the same origin checks the',
          '   * local panel uses (same-origin only, no POST).',
          '   */',
          '  ctx.webServer.register({',
          "    kind: 'exact',",
          "    path: '/compat-spike/ping',",
          '    handler: (request, response) => {',
          "      response.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' })",
          "      response.end(JSON.stringify({ ok: true, from: 'host-route', at: 'spike' }))",
          '    },',
          '  })',
          "  console.log('SPIKE_ROUTE ' + JSON.stringify({ ok: true, path: '/compat-spike/ping' }))",
          '}',
          '',
        ]
      : [
          "import { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'",
          '',
          "const MARKER_KEY = '@deepseek-ai/dsh-typert-protocol/remote-methods'",
          '',
          'export class SpikeGateway extends TypertRemoteService {',
          '  constructor(ctx) {',
          "    super(ctx, 'compatSpike')",
          '    /*',
          '     * Report what the registry actually holds, from inside the Host: this is the half of the',
          '     * question no browser can answer (a missing endpoint and an unreachable one look identical',
          '     * in the UI).',
          '     */',
          '    setTimeout(() => {',
          '      try {',
          "        const registry = ctx.get('typert')",
          '        const found = typeof registry?.local?.list === \'function\' ? registry.local.list() : null',
          '        const endpoints = Array.isArray(found) ? found.map((entry) => `${entry?.namespace}/${entry?.method}`) : null',
          "        console.log(`SPIKE_REGISTRY ${JSON.stringify({ ok: true, endpoints })}`)",
          '      } catch (error) {',
          "        console.log(`SPIKE_REGISTRY ${JSON.stringify({ ok: false, error: String(error && error.message ? error.message : error) })}`)",
          '      }',
          '    }, 1500)',
          '  }',
          '',
          '  ping() {',
          "    return { ok: true, from: 'host-remote', at: 'spike' }",
          '  }',
          '}',
          '',
          'Object.defineProperty(SpikeGateway.prototype, MARKER_KEY, {',
          '  value: { version: 1, methods: [{ method: \'ping\', invocation: { kind: \'direct\' } }] },',
          '  configurable: true,',
          '})',
          '',
          'export default SpikeGateway',
          '',
        ]
  writeFileSync(join(pkgDir, 'index.js'), hostHalf.join('\n'), 'utf8')
  writeFileSync(
    join(pkgDir, 'typert.host.js'),
    [
      "import { createTypertRemoteInfo } from '@deepseek-ai/dsh-typert-protocol/remote-info'",
      "import { z } from 'zod'",
      '',
      'const result = () =>',
      "  z.object({ ok: z.boolean(), from: z.string(), at: z.string() })",
      '',
      'const $remote = createTypertRemoteInfo({',
      "  package: 'dsh-remote-spike',",
      '  methods: {',
      "    'compatSpike/ping': {",
      "      service: 'compatSpike',",
      "      description: 'Spike: answer a constant so the channel can be observed end to end.',",
      "      invocation: { kind: 'direct' },",
      '      parameters: [],',
      '      result: {',
      "        mode: 'strict',",
      "        typeSymbol: 'dsh-remote-spike#PingResult',",
      '        create: result,',
      "        description: 'Constant answer used only to prove the Remote channel works.',",
      '      },',
      '    },',
      '  },',
      '}, z)',
      '',
      'export const TYPERT = {',
      "  package: 'dsh-remote-spike',",
      "  face: 'host',",
      '  schemas: [],',
      '  get invocations() { return $remote.descriptors },',
      "  model: { services: [], events: [], objects: [] },",
      '}',
      '',
    ].join('\n'),
    'utf8',
  )
  const clientHalf =
    channel === 'route'
      ? [
          '/* Browser half (route channel): same-origin GET with the session cookie, then publish. */',
          'window.__ModuleLoader__.load({',
          "  id: 'dsh-remote-spike',",
          '  factory: (require) => {',
          '    function apply(ctx) {',
          '      const publish = (value) => {',
          '        try {',
          '          window.__dshSpike = value',
          '        } catch {}',
          '      }',
          "      fetch('/compat-spike/ping', { credentials: 'include' })",
          '        .then((response) => response.json())',
          '        .then((value) => publish({ ok: true, value }))',
          "        .catch((error) => publish({ ok: false, reason: String(error && error.message ? error.message : error) }))",
          '    }',
          '    return { apply }',
          '  },',
          '})',
          '',
        ]
      : [
          '/* Browser half (typert channel): call the Remote and publish the answer for CDP to read. */',
          'window.__ModuleLoader__.load({',
          "  id: 'dsh-remote-spike',",
          '  factory: (require) => {',
          "    const inject = ['remote', 'remote.compatSpike']",
          '    function apply(ctx) {',
          '      const publish = (value) => {',
          '        try {',
          '          window.__dshSpike = value',
          '        } catch {}',
          '      }',
          '      try {',
          '        const remote = ctx && ctx.remote',
          '        const ns = remote && remote.compatSpike',
          "        if (!ns || typeof ns.ping !== 'function') {",
          "          publish({ ok: false, reason: 'remote namespace missing', keys: remote ? Object.keys(remote) : null, namespaces: remote && remote.namespaces ? (Array.isArray(remote.namespaces) ? remote.namespaces : Object.keys(remote.namespaces)) : null })",
          '          return',
          '        }',
          '        Promise.resolve(ns.ping())',
          '          .then((value) => publish({ ok: true, value }))',
          "          .catch((error) => publish({ ok: false, reason: String(error && error.message ? error.message : error) }))",
          '      } catch (error) {',
          "        publish({ ok: false, reason: String(error && error.message ? error.message : error) })",
          '      }',
          '    }',
          '    return { inject, apply }',
          '  },',
          '})',
          '',
        ]
  writeFileSync(join(pkgDir, 'client.js'), clientHalf.join('\n'), 'utf8')
  return pkgDir
}

function run(command, args, options) {
  return new Promise((resolvePromise) => {
    const child = spawn(command, args, { cwd: options.cwd, env: options.env, shell: false, windowsHide: true })
    let stdout = ''
    let stderr = ''
    child.stdout?.on('data', (chunk) => {
      stdout += String(chunk)
    })
    child.stderr?.on('data', (chunk) => {
      stderr += String(chunk)
    })
    const timer = setTimeout(() => child.kill('SIGKILL'), options.timeoutMs ?? 600_000)
    child.on('close', (code) => {
      clearTimeout(timer)
      resolvePromise({ code, stdout, stderr })
    })
  })
}

async function main() {
  const dir = writeSpikePackage()
  record('bundle', 'passed', channel === 'route' ? 'spike package written: route host half + fetch client half' : 'spike package written: ./typert + Remote service + client half', {
    channel,
    files: ['package.json', 'cordis.patch.yml', 'index.js', 'typert.host.js', 'client.js'],
  })

  mkdirSync(profileDir, { recursive: true })
  writeFileSync(
    join(profileDir, 'package.json'),
    `${JSON.stringify(
      {
        name: 'dsh-profile-remote-spike',
        private: true,
        dependencies: {
          '@deepseek-ai/dsh': '0.2.1-rc.4',
          '@deepseek-ai/dsh-base': '0.2.1-rc.4',
          '@deepseek-ai/dsh-web-app': '0.2.1-rc.4',
          'dsh-remote-spike': `file:${dir.replaceAll('\\', '/')}`,
        },
        dsh: { profile: { bundles: ['@deepseek-ai/dsh-base', '@deepseek-ai/dsh-web-app', 'dsh-remote-spike'] } },
      },
      null,
      2,
    )}\n`,
    'utf8',
  )
  writeFileSync(join(profileDir, 'cordis.yml'), '[]\n', 'utf8')
  writeFileSync(
    join(profileDir, 'pnpm-workspace.yaml'),
    ['# written by dsh-triage record_remote_spike (R33): do not fail the install over unapproved builds.', 'strictDepBuilds: false', ''].join('\n'),
    'utf8',
  )
  const env = { ...process.env, DSH_HOME: home, npm_config_userconfig: join(root, 'empty-npmrc') }
  writeFileSync(join(root, 'empty-npmrc'), '', 'utf8')

  const installed = await run(process.execPath, [dshMain, 'plugin', '--profile', 'web', 'install'], { cwd: home, env, timeoutMs: 600_000 })
  const installDetail = clean(`${installed.stdout}\n${installed.stderr}`).trim().slice(-900)
  record('install', installed.code === 0 ? 'passed' : 'failed', installDetail || `exit ${installed.code}`)
  if (installed.code !== 0) return await finish({ remote_callable: 'unmeasured' }, typeof output === 'string' ? output : '')

  const host = spawn(process.execPath, [dshMain, '--profile', 'web', '--port', '0', '--no-open'], { cwd: home, env, windowsHide: true })
  hostPid = host.pid
  let output = ''
  host.stdout?.on('data', (chunk) => {
    output += String(chunk)
  })
  host.stderr?.on('data', (chunk) => {
    output += String(chunk)
  })
  const url = await new Promise((resolvePromise) => {
    const started = Date.now()
    const timer = setInterval(() => {
      const match = /http:\/\/127\.0\.0\.1:(\d+)\/\?token=[A-Za-z0-9._~-]+/.exec(output) ?? /http:\/\/127\.0\.0\.1:(\d+)/.exec(output)
      if (match !== null) {
        clearInterval(timer)
        resolvePromise(match[0])
        return
      }
      if (Date.now() - started > bootTimeoutMs) {
        clearInterval(timer)
        resolvePromise(null)
      }
    }, 200)
  })
  try {
    if (url === null) {
      record('boot', 'failed', clean(output).slice(-500) || 'no URL printed')
      return await finish({ remote_callable: 'unmeasured' }, typeof output === 'string' ? output : '')
    }
    const base = url.replace(/\?.*$/, '')
    record('boot', 'passed', `host printed ${base}`)

    // The Host's own words about the typert manifest: registration failures are logged, not thrown.
    const registryLine = /SPIKE_REGISTRY (.+)/.exec(output)
    let registry = null
    if (registryLine !== null) {
      try {
        registry = JSON.parse(registryLine[1])
      } catch {
        registry = null
      }
    }
    if (channel === 'route') {
      const line = /SPIKE_ROUTE (.+)/.exec(output)
      let report = null
      if (line !== null) {
        try {
          report = JSON.parse(line[1])
        } catch {
          report = null
        }
      }
      record(
        'route',
        report === null ? 'unmeasured' : report.ok === true ? 'passed' : 'failed',
        report === null ? 'the Host never reported the route registration (the spike plugin may not have mounted)' : JSON.stringify(report),
        { path: report?.path ?? null },
      )
    } else {
      const typertErrors = output
        .split('\n')
        .filter((line) => /typert|TYPERT/i.test(line))
        .slice(0, 12)
        .map(clean)
      record(
        'registry',
        registry === null ? 'unmeasured' : registry.ok === true ? 'passed' : 'failed',
        registry === null ? 'the Host never printed a registry report (the spike plugin may not have mounted)' : JSON.stringify(registry),
        { endpoints: registry?.endpoints ?? null, typert_log_lines: typertErrors },
      )
    }

    const page = await fetchPage(base, url)
    const listed = extractClientModule(page.text, 'dsh-remote-spike')
    record('graph', listed === null ? 'failed' : 'passed', listed === null ? 'the boot document does not compose dsh-remote-spike/client.js' : `composed as ${clean(listed).slice(0, 120)}`, {
      client_module_listed: listed !== null,
      html_bytes: page.text.length,
    })

    const browser = findBrowser({ explicit: argOf('--browser', null) })
    let call = { ok: null, detail: 'no browser found' }
    if (browser !== null) call = await checkCall(browser, base, page.cookie)
    record('call', call.ok === true ? 'passed' : call.ok === false ? 'failed' : 'unmeasured', call.detail, {
      browser: browser === null ? null : basename(browser),
      marker: call.marker ?? null,
    })
    return await finish({ remote_callable: call.ok === true ? 'yes' : call.ok === false ? 'no' : 'unmeasured' }, output)
  } finally {
    await killTree(host.pid)
  }
}

/** Read `window.__dshSpike` from a real page: the answer is what the browser actually got. */
async function checkCall(browser, pageUrl, cookie) {
  const userDataDir = join(root, 'cdp-user-data')
  mkdirSync(userDataDir, { recursive: true })
  const chrome = spawn(
    browser,
    ['--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check', '--remote-debugging-port=0', `--user-data-dir=${userDataDir}`, 'about:blank'],
    { windowsHide: true },
  )
  try {
    const portFile = join(userDataDir, 'DevToolsActivePort')
    const port = await new Promise((resolvePromise) => {
      const started = Date.now()
      const timer = setInterval(() => {
        if (existsSync(portFile)) {
          const first = readFileSync(portFile, 'utf8').split('\n')[0] ?? ''
          clearInterval(timer)
          resolvePromise(Number(first))
          return
        }
        if (Date.now() - started > 20_000) {
          clearInterval(timer)
          resolvePromise(null)
        }
      }, 100)
    })
    if (port === null) return { ok: null, detail: 'browser never exposed a debugging port' }
    const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()
    const target = Array.isArray(targets) ? targets.find((entry) => entry.type === 'page') : null
    if (target === null || target === undefined) return { ok: null, detail: 'no page target' }
    const socket = new WebSocket(target.webSocketDebuggerUrl)
    const pending = new Map()
    let nextId = 1
    socket.addEventListener('message', (event) => {
      const message = JSON.parse(String(event.data))
      const waiter = pending.get(message.id)
      if (waiter === undefined) return
      pending.delete(message.id)
      if (message.error) waiter.reject(new Error(message.error.message))
      else waiter.resolve(message.result)
    })
    const send = (method, params = {}) =>
      new Promise((resolvePromise, rejectPromise) => {
        const id = nextId++
        const timer = setTimeout(() => {
          pending.delete(id)
          rejectPromise(new Error(`CDP ${method} timed out`))
        }, 20_000)
        pending.set(id, {
          resolve: (value) => {
            clearTimeout(timer)
            resolvePromise(value)
          },
          reject: (error) => {
            clearTimeout(timer)
            rejectPromise(error)
          },
        })
        socket.send(JSON.stringify({ id, method, params }))
      })
    await new Promise((resolvePromise, rejectPromise) => {
      socket.addEventListener('open', () => resolvePromise(undefined), { once: true })
      socket.addEventListener('error', () => rejectPromise(new Error('cdp socket error')), { once: true })
    })
    await send('Page.enable')
    await send('Network.enable')
    for (const pair of cookie.split(';')) {
      const [name, ...rest] = pair.trim().split('=')
      const value = rest.join('=')
      if (name === '' || value === '') continue
      await send('Network.setCookie', { name, value, url: pageUrl })
    }
    await send('Page.navigate', { url: pageUrl })
    let marker = null
    for (let attempt = 0; attempt < 15; attempt += 1) {
      await new Promise((resolvePromise) => setTimeout(resolvePromise, 800))
      const evaluated = await send('Runtime.evaluate', { expression: 'JSON.stringify(window.__dshSpike || null)', returnByValue: true })
      const value = evaluated?.result?.value
      if (typeof value === 'string' && value !== 'null') {
        marker = JSON.parse(value)
        break
      }
    }
    socket.close()
    if (marker === null) return { ok: null, detail: 'the page never published window.__dshSpike (client half never ran?)' }
    if (marker.ok === true) return { ok: true, detail: `the browser called compatSpike/ping and got ${JSON.stringify(marker.value)}`, marker }
    return { ok: false, detail: `the client ran but the call failed: ${String(marker.reason)}`, marker }
  } finally {
    await killTree(chrome.pid)
  }
}

async function fetchPage(base, tokenUrl, cookie = '') {
  let current = cookie
  if (current === '') {
    const first = await fetch(tokenUrl, { redirect: 'manual' })
    current = (first.headers.getSetCookie?.() ?? []).map((value) => value.split(';')[0]).join('; ')
    const location = first.headers.get('location')
    if (location === null) return { status: first.status, text: '', contentType: null, cookie: current }
    const next = await fetch(`${base}${location.replace(/^\.?\//, '')}`, { headers: { cookie: current, accept: 'text/html' }, redirect: 'manual' })
    return { status: next.status, text: next.status === 200 ? await next.text() : '', contentType: next.headers.get('content-type'), cookie: current }
  }
  const response = await fetch(tokenUrl, { headers: { cookie: current }, redirect: 'manual' })
  return { status: response.status, text: response.status === 200 ? await response.text() : '', contentType: response.headers.get('content-type'), cookie: current }
}

function extractClientModule(html, packageName) {
  const refs = [...html.matchAll(/["']([^"']*plugins\/[^"']+)["']/g)].map((match) => match[1].replaceAll('&amp;', '&'))
  for (const ref of refs) {
    if (!ref.includes(packageName)) continue
    return ref.startsWith('/') ? ref : `/${ref}`
  }
  return null
}

async function killTree(pid) {
  if (pid === undefined) return
  await new Promise((resolvePromise) => {
    const child = spawn('taskkill', ['/pid', String(pid), '/T', '/F'], { windowsHide: true })
    child.on('close', () => resolvePromise())
    child.on('error', () => resolvePromise())
  })
}

async function finish(outcome, hostLog = '') {
  await killTree(hostPid)
  let removed = false
  let lastError = null
  for (let attempt = 0; attempt < 10 && !removed; attempt += 1) {
    try {
      rmSync(root, { recursive: true, force: true })
      removed = true
    } catch (error) {
      lastError = error
      await new Promise((resolvePromise) => setTimeout(resolvePromise, 500))
    }
  }
  record('cleanup', removed ? 'passed' : 'failed', removed ? 'sandbox removed' : `leaked: ${String(lastError)}`, { removed })
  const payload = {
    schema_version: 1,
    produced_by: 'scripts/record_remote_spike.mjs',
    generated_at: stamp,
    label,
    channel,
    outcome,
    steps,
    host_log: clean(hostLog)
      .replace(/\\?token=[A-Za-z0-9._~-]+/g, '?token=<redacted>')
      .split('\\n')
      .slice(-60),
    limits: [
      'this spike proves a CHANNEL (a third-party package answering a read-only Remote call) and nothing about conclusions; the answer is a constant',
      'the marker descriptor is hand-written under the protocol key instead of using the @Remote decorator, because plain .js has no decorator syntax — a product implementation in TypeScript may take the supported path',
      'one sandbox runtime (0.2.1-rc.4) on one Windows machine; the package is installed from a local directory, no registry and no credentials',
    ],
  }
  const text = `${JSON.stringify(payload, null, 2)}\n`
  mkdirSync(outDir, { recursive: true })
  const target = join(outDir, `${label}-${stamp.replaceAll(':', '-')}.json`)
  writeFileSync(target, text, 'utf8')
  writeFileSync(`${target}.sha256`, `${sha256(text)}\n`, 'utf8')
  process.stdout.write(`${basename(target)} · ${steps.map((step) => `${step.id}:${step.status}`).join(' ')}\n`)
  process.exitCode = 0
}

await main()
